      st: { reflux: 'Reflujo en la vena espermática.', heat: 'Calor y estrés oxidativo en el testículo.', asymmetry: 'El testículo afectado crece menos.', semen: 'Baja concentración y motilidad.', microsurgery: 'Ligadura microquirúrgica de las venas.', embolization: 'Embolización de la vena espermática.' },
      ev: { rightSided: 'Varicocele derecho aislado: descartar masa retroperitoneal.', microsurgery: 'Varicocelectomía microquirúrgica subinguinal.', embolization: 'Embolización percutánea.', subclinicalNoBenefit: 'Varicocele subclínico: sin beneficio demostrado.', asym20: 'Asimetría testicular > 20 %.', improved: 'El seminograma mejora (≈ 3 meses, un ciclo de espermatogénesis).' },
